  SID CHAR(5) PRIMARY KEY NOT NULL,
  NAME VARCHAR(40),
  SEX CHAR(1),
  CLASS CHAR(2),
  CNO INT,
  CID INT,
  CHECK (LENGTH(SID) = 5),
  CHECK (SEX IN ('M', 'F')),
  CHECK (CLASS IN ('1A', '1B', '1C', '1D')),
  CHECK (CNO BETWEEN 1 AND 30),
  FOREIGN KEY (CID) REFERENCES CLUB(CID)
);
